-- 005: meaning-based search (pgvector) and Telegram alerts.
--
-- Safe to run more than once: every statement is idempotent.
--
-- Embeddings are 384-dimensional vectors from gte-small, generated by the
-- `embed` Edge Function (Supabase's built-in model, so no third-party key).
-- There is deliberately no ANN index: upcoming events number in the
-- thousands, where an exact scan takes milliseconds, and an HNSW index would
-- silently drop rows once the time and distance filters are applied.

CREATE EXTENSION IF NOT EXISTS vector WITH SCHEMA extensions;

ALTER TABLE events ADD COLUMN IF NOT EXISTS embedding extensions.vector(384);
-- md5 of the text that was embedded, so edited listings are re-embedded and
-- unchanged ones are not (the scraper rewrites every row on each run).
ALTER TABLE events ADD COLUMN IF NOT EXISTS embedding_hash TEXT;

-- The text an event is embedded from. Kept in SQL so the hash and the text
-- can never disagree.
CREATE OR REPLACE FUNCTION event_embedding_text(
    p_title TEXT,
    p_category event_category,
    p_description TEXT,
    p_location TEXT,
    p_city TEXT
) RETURNS TEXT
LANGUAGE sql IMMUTABLE AS $$
    SELECT left(
        concat_ws('. ',
            p_title,
            initcap(p_category::text),
            nullif(left(coalesce(p_description, ''), 700), ''),
            nullif(concat_ws(', ', nullif(p_location, ''), nullif(p_city, '')), '')
        ),
        1200
    )
$$;

-- Upcoming events whose embedding is missing or stale.
CREATE OR REPLACE FUNCTION events_pending_embedding(batch_size INT DEFAULT 64)
RETURNS TABLE (id UUID, content TEXT, content_hash TEXT)
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = public, extensions AS $$
    SELECT e.id, t.content, md5(t.content)
    FROM events e
    CROSS JOIN LATERAL (
        SELECT event_embedding_text(e.title, e.category, e.description, e.location_name, e.city) AS content
    ) t
    WHERE e.start_time >= now() - interval '1 day'
      AND (e.embedding IS NULL OR e.embedding_hash IS DISTINCT FROM md5(t.content))
    ORDER BY e.start_time
    LIMIT batch_size
$$;

CREATE OR REPLACE FUNCTION events_pending_embedding_count()
RETURNS INT
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = public, extensions AS $$
    SELECT count(*)::int
    FROM events e
    WHERE e.start_time >= now() - interval '1 day'
      AND (
        e.embedding IS NULL
        OR e.embedding_hash IS DISTINCT FROM md5(
            event_embedding_text(e.title, e.category, e.description, e.location_name, e.city)
        )
      )
$$;

-- items: [{"id": "<uuid>", "hash": "<md5>", "embedding": "[0.1,0.2,...]"}]
CREATE OR REPLACE FUNCTION set_event_embeddings(items JSONB)
RETURNS INT
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, extensions AS $$
DECLARE
    n INT;
BEGIN
    UPDATE events e
    SET embedding = (x->>'embedding')::extensions.vector(384),
        embedding_hash = x->>'hash'
    FROM jsonb_array_elements(items) AS x
    WHERE e.id = (x->>'id')::uuid;
    GET DIAGNOSTICS n = ROW_COUNT;
    RETURN n;
END;
$$;

-- Writing and listing pending work is for the server only.
REVOKE EXECUTE ON FUNCTION events_pending_embedding(INT) FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION events_pending_embedding_count() FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION set_event_embeddings(JSONB) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION events_pending_embedding(INT) TO service_role;
GRANT EXECUTE ON FUNCTION events_pending_embedding_count() TO service_role;
GRANT EXECUTE ON FUNCTION set_event_embeddings(JSONB) TO service_role;

-- Nearest events by meaning, optionally within a radius and time window.
-- Same columns as search_events, plus similarity (0..1) and created_at.
DROP FUNCTION IF EXISTS match_events(extensions.vector, DOUBLE PRECISION, DOUBLE PRECISION, DOUBLE PRECISION, TIMESTAMPTZ, TIMESTAMPTZ, INT, DOUBLE PRECISION);
CREATE FUNCTION match_events(
    query_embedding extensions.vector(384),
    p_lat DOUBLE PRECISION DEFAULT NULL,
    p_lng DOUBLE PRECISION DEFAULT NULL,
    radius_km DOUBLE PRECISION DEFAULT 40.0,
    from_time TIMESTAMPTZ DEFAULT now(),
    to_time TIMESTAMPTZ DEFAULT NULL,
    match_count INT DEFAULT 30,
    min_similarity DOUBLE PRECISION DEFAULT 0
)
RETURNS TABLE (
    id UUID,
    title TEXT,
    description TEXT,
    category event_category,
    start_time TIMESTAMPTZ,
    end_time TIMESTAMPTZ,
    location_name TEXT,
    address TEXT,
    city TEXT,
    country TEXT,
    lat DOUBLE PRECISION,
    lng DOUBLE PRECISION,
    image_url TEXT,
    url TEXT,
    price_min NUMERIC,
    price_max NUMERIC,
    is_free BOOLEAN,
    source TEXT,
    distance_km DOUBLE PRECISION,
    similarity DOUBLE PRECISION,
    created_at TIMESTAMPTZ
)
LANGUAGE sql STABLE
SET search_path = public, extensions AS $$
    SELECT
        e.id, e.title, e.description, e.category,
        e.start_time, e.end_time, e.location_name,
        e.address, e.city, e.country,
        ST_Y(e.coords::geometry), ST_X(e.coords::geometry),
        e.image_url, e.url, e.price_min, e.price_max,
        e.is_free, e.source,
        CASE
            WHEN p_lat IS NOT NULL AND e.coords IS NOT NULL
            THEN ST_Distance(e.coords, ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography) / 1000.0
        END,
        1 - (e.embedding <=> query_embedding),
        e.created_at
    FROM events e
    WHERE e.embedding IS NOT NULL
      AND e.start_time >= from_time
      AND (to_time IS NULL OR e.start_time <= to_time)
      AND (
        p_lat IS NULL
        OR (e.coords IS NOT NULL AND ST_DWithin(
            e.coords,
            ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography,
            radius_km * 1000.0
        ))
      )
      AND 1 - (e.embedding <=> query_embedding) >= min_similarity
    ORDER BY e.embedding <=> query_embedding
    LIMIT match_count
$$;

-- "More like this": upcoming events closest in meaning to one event, near it.
DROP FUNCTION IF EXISTS similar_events(UUID, INT);
CREATE FUNCTION similar_events(p_event_id UUID, match_count INT DEFAULT 6)
RETURNS TABLE (
    id UUID,
    title TEXT,
    description TEXT,
    category event_category,
    start_time TIMESTAMPTZ,
    end_time TIMESTAMPTZ,
    location_name TEXT,
    address TEXT,
    city TEXT,
    country TEXT,
    lat DOUBLE PRECISION,
    lng DOUBLE PRECISION,
    image_url TEXT,
    url TEXT,
    price_min NUMERIC,
    price_max NUMERIC,
    is_free BOOLEAN,
    source TEXT,
    distance_km DOUBLE PRECISION,
    similarity DOUBLE PRECISION,
    created_at TIMESTAMPTZ
)
LANGUAGE sql STABLE
SET search_path = public, extensions AS $$
    SELECT
        e.id, e.title, e.description, e.category,
        e.start_time, e.end_time, e.location_name,
        e.address, e.city, e.country,
        ST_Y(e.coords::geometry), ST_X(e.coords::geometry),
        e.image_url, e.url, e.price_min, e.price_max,
        e.is_free, e.source,
        CASE
            WHEN src.coords IS NOT NULL AND e.coords IS NOT NULL
            THEN ST_Distance(e.coords, src.coords) / 1000.0
        END,
        1 - (e.embedding <=> src.embedding),
        e.created_at
    FROM events src
    JOIN events e ON e.id <> src.id
    WHERE src.id = p_event_id
      AND src.embedding IS NOT NULL
      AND e.embedding IS NOT NULL
      AND e.start_time >= now()
      -- Different listings of the same event are not "similar", they are the same.
      AND lower(e.title) <> lower(src.title)
      AND (
        src.coords IS NULL
        OR e.coords IS NULL
        OR ST_DWithin(e.coords, src.coords, 60000)
      )
    ORDER BY e.embedding <=> src.embedding
    LIMIT match_count
$$;

-- ---------------------------------------------------------------------------
-- Telegram alerts
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS alerts (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    query TEXT NOT NULL CHECK (char_length(query) BETWEEN 3 AND 300),
    city TEXT,
    lat DOUBLE PRECISION,
    lng DOUBLE PRECISION,
    radius_km DOUBLE PRECISION NOT NULL DEFAULT 40,
    query_embedding extensions.vector(384) NOT NULL,
    -- Set once the person presses Start in Telegram.
    telegram_chat_id BIGINT,
    -- One-time token carried in the t.me deep link.
    link_token TEXT NOT NULL UNIQUE,
    active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_checked_at TIMESTAMPTZ
);

CREATE INDEX IF NOT EXISTS idx_alerts_chat ON alerts (telegram_chat_id) WHERE telegram_chat_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_alerts_active ON alerts (active) WHERE active;

CREATE TABLE IF NOT EXISTS alert_deliveries (
    alert_id UUID NOT NULL REFERENCES alerts (id) ON DELETE CASCADE,
    event_id UUID NOT NULL REFERENCES events (id) ON DELETE CASCADE,
    sent_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (alert_id, event_id)
);

-- Chat ids are personal data: no anon or authenticated access at all. The
-- server uses the service role, which bypasses RLS.
ALTER TABLE alerts ENABLE ROW LEVEL SECURITY;
ALTER TABLE alert_deliveries ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON alerts FROM anon, authenticated;
REVOKE ALL ON alert_deliveries FROM anon, authenticated;

-- Make PostgREST pick up the new functions and tables immediately.
NOTIFY pgrst, 'reload schema';
